import{e as r,ab as a,a1 as i,m as n,r as s,p as o}from"./chunks/framework.BGh0NSIy.js";const b=JSON.parse('{"title":"Monthly Updates [June]","description":"June 2024 updates","frontmatter":{"title":"Monthly Updates [June]","description":"June 2024 updates","date":"2024-06-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/june-2024.md","filePath":"posts/june-2024.md"}'),l={name:"posts/june-2024.md"};function h(d,e,p,f,m,c){const t=a("Post");return i(),n("div",null,[s(t,{authors:"nbats"}),e[0]||(e[0]=o('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Added <a href="https://fmhy.net/gaming-tools#switch-homebrew" target="_blank" rel="noreferrer">Switch</a>, <a href="https://fmhy.net/gaming-tools#wii-u-wii-homebrew" target="_blank" rel="noreferrer">Wii U / Wii</a>, <a href="https://fmhy.net/gaming-tools#_3ds-ds-homebrew" target="_blank" rel="noreferrer">3DS / DS</a>, and <a href="https://fmhy.net/gaming-tools#playstation-homebrew" target="_blank" rel="noreferrer">PlayStation</a> sections to Homebrew.</p></li><li><p>Added <a href="https://fmhy.net/gaming#virtual-reality" target="_blank" rel="noreferrer">Virtual Reality</a> and <a href="https://fmhy.net/gaming-tools#game-saves" target="_blank" rel="noreferrer">Game Save</a> sections to Gaming.</p></li><li><p>Added <a href="https://fmhy.net/developer-tools#dev-communities" target="_blank" rel="noreferrer">Dev Communities</a> and <a href="https://fmhy.net/developer-tools#reverse-engineering" target="_blank" rel="noreferrer">Reverse Engineering</a> sections to Dev Tools.</p></li><li><p>Added <a href="https://fmhy.net/linux-macos#linux-communities" target="_blank" rel="noreferrer">Linux Communities</a> section to Linux.</p></li><li><p>Added <a href="https://fmhy.net/misc#flights" target="_blank" rel="noreferrer">Flights</a> section to Travel.</p></li><li><p>Organized the Maps section and added multiple <a href="https://fmhy.net/misc#maps" target="_blank" rel="noreferrer">new subsections</a> to it.</p></li><li><p>Debloated <a href="https://fmhy.net/misc#indexes" target="_blank" rel="noreferrer">Indexes</a>, <a href="https://fmhy.net/misc#multi-tool-sites" target="_blank" rel="noreferrer">Multi-Tool</a>, <a href="https://fmhy.net/privacy#file-scanners" target="_blank" rel="noreferrer">File Scanners</a>, <a href="https://fmhy.net/internet-tools#archiving" target="_blank" rel="noreferrer">Archiving</a>, and <a href="https://fmhy.net/storage#music-sheet-collections" target="_blank" rel="noreferrer">Sheet Music</a> sections.</p></li><li><p>Re-added our <a href="https://github.com/WindowsAurora/FMHYFilterlist/" target="_blank" rel="noreferrer">Unsafe Sites Filter</a>. This can be added to uBlock to stop anything in <a href="https://fmhy.net/unsafe" target="_blank" rel="noreferrer">unsafe sites</a> from loading in your browser.</p></li><li><p>We compared FMHY to the badware filter list to make sure we didn&#39;t have anything on it, <a href="https://ibb.co/9TQ6Nnv" target="_blank" rel="noreferrer">and we didn&#39;t</a>.</p></li><li><p>Added an optional <a href="https://pastebin.com/MDnQPKP3" target="_blank" rel="noreferrer">alternative logo</a> to our website.</p></li></ul><hr><h3 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h3><ul><li><p>Starred both squid.wtf and MP3 Daddy in <a href="https://fmhy.net/audio#audio-ripping-sites" target="_blank" rel="noreferrer">Audio Ripping</a>. Deezer ripping sites both capable of getting FLAC files.</p></li><li><p>Starred <a href="https://fmhy.net/ai#online-chatbots" target="_blank" rel="noreferrer">Morphic</a> in Online Chatbots. GPT-4o-powered search w/ no limits.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#rom-sites" target="_blank" rel="noreferrer">ROM Heaven</a> in ROM sites. Badass new ROM site with single-click DDL and a high-quality UI.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#minecraft-tools" target="_blank" rel="noreferrer">Eaglercraft</a> in Minecraft as it&#39;s started getting updates again.</p></li><li><p>Starred <a href="https://fmhy.net/file-tools#file-archivers" target="_blank" rel="noreferrer">CompactGUI</a> in File Archivers. Very <a href="https://ibb.co/xm23Xbh" target="_blank" rel="noreferrer">useful</a> archiver with a nice UI.</p></li><li><p>Starred <a href="https://fmhy.net/audio#spotify-adblockers" target="_blank" rel="noreferrer">Spicetify</a> in Spotify Adblockers. This has adblock plugins that work just as well as SpotX.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#reddit-tools" target="_blank" rel="noreferrer">UI Revert Script</a> in Reddit Tools. Restores Reddit&#39;s 2023 UI.</p></li><li><p>Starred <a href="https://fmhy.net/storage#to-do-apps" target="_blank" rel="noreferrer">Snaptick</a> in Android To-Do Apps. Very feature-rich to-do app.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#twitch-adblockers" target="_blank" rel="noreferrer">PurpleAdblock</a> in Twitch Adblockers. Got an update recently and seems to be working again.</p></li><li><p>Starred <a href="https://fmhy.net/image-tools#image-viewers" target="_blank" rel="noreferrer">ImageGlass</a> in Image Viewers. Popular lightweight image viewer with a nice UI.</p></li><li><p>Starred <a href="https://fmhy.net/storage#fun-indexes" target="_blank" rel="noreferrer">Neal.fun</a> in Fun Indexes. OG site with lots of fun games / experiments.</p></li><li><p>Starred <a href="https://fmhy.net/privacy#dns-adblocking" target="_blank" rel="noreferrer">Pi-hole</a> in DNS Adblockers as their lists are more updated than NextDNS.</p></li><li><p>Starred <a href="https://fmhy.net/ai#online-chatbots" target="_blank" rel="noreferrer">ChatGPT</a> in Online Chatbots as they&#39;re adding GPT-4o to the <a href="https://help.openai.com/en/articles/7102672-how-can-i-access-gpt-4-gpt-4-turbo-and-gpt-4o" target="_blank" rel="noreferrer">free tier</a>.</p></li></ul><hr><h3 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h3><ul><li><p>Removed both moo and media drives as neither work anymore.</p></li><li><p>Removed The Movie Archive as it&#39;s shut down.</p></li><li><p>Removed Subscene as they&#39;ve <a href="https://ibb.co/SVX41NW" target="_blank" rel="noreferrer">closed</a>.</p></li><li><p>Removed neofetch as it&#39;s been archived.</p></li><li><p>Unstarred Bloxstrap as the <a href="https://github.com/pizzaboxer/bloxstrap/wiki/Addressing-usability-problems-with-Bloxstrap-v2.5.4" target="_blank" rel="noreferrer">dev doesn&#39;t have time</a> currently to keep it updated.</p></li><li><p>Unstarred NextDNS as their filter lists include negligent ones (like energized) which cause a bunch of issues, including fmhy.net getting blocked.</p></li></ul>',9))])}const u=r(l,[["render",h]]);export{b as __pageData,u as default};
